const sessionManager = require("./session-manager").getInstance(null); // Will be passed later

module.exports = function(RED) {
    const express = RED.httpNode || require('express')();
    const router = express.Router();

    router.post('/ivr/callback', async (req, res) => {
        try {
            const { sessionId, dtmfDigits, callerNumber, eventType } = req.body;

            if (!sessionId) {
                return res.status(400).send('Missing sessionId');
            }

            const session = await sessionManager.getSession(sessionId);
            if (!session) {
                console.warn(`Session not found: ${sessionId}`);
                return res.status(404).send('Session not found');
            }

            // Handle different Africa's Talking events
            if (eventType === 'Digits' || dtmfDigits) {
                // Resume the waiting node
                await resumeFlow(RED, session, dtmfDigits);
            }

            res.status(200).send('OK'); // Always acknowledge quickly
        } catch (err) {
            console.error('Webhook error:', err);
            res.status(500).send('Error');
        }
    });

    // Mount the route
    RED.httpNode.use('/kumva', router);
    console.log("Kumva IVR Webhook mounted at /kumva/ivr/callback");

    // Expose for external registration if needed
    RED.kumva = RED.kumva || {};
    RED.kumva.webhookHandler = router;
};

// Simple resume helper (will be expanded in ivr-engine)
async function resumeFlow(RED, session, response) {
    // Find all nodes in the flow and look for the one matching currentNodeId
    const flow = RED.nodes.getFlow(session.flowId);
    if (!flow) return;

    // For now, we log. In next version we'll properly inject into the waiting node
    console.log(`Resuming session ${session.sessionId} with response: ${response}`);
    
    // TODO: Proper node resume logic using RED.events or internal message injection
    RED.events.emit('kumva:resume', {
        sessionId: session.sessionId,
        response: response,
        nodeId: session.currentNodeId
    });
}